/* @autogenerated */
package net.civeira.phylax.feature.observe.metric;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class MetricRecoveryUnitTest {

  private static final long HOUR = MetricDeriver.HOUR;
  private static final long MINUTE = MetricDeriver.MINUTE;

  private static MetricPoint minute(final long ts, final long count, final long errors) {
    Histogram histogram = new Histogram();
    for (int i = 0; i < count; i++) {
      histogram.add(10);
    }
    return new MetricPoint(ts, MINUTE, "api", "/orders", "GET", count, errors, count * 10.0,
        histogram.counts());
  }

  @Test
  @DisplayName("The rollup of minute points adds counts, errors, durations and buckets per series and hour")
  void rollup() {
    long hour = 10 * HOUR;
    List<MetricPoint> hours = MetricDeriver.rollup(
        List.of(minute(hour, 3, 1), minute(hour + 5 * MINUTE, 2, 0), minute(hour + HOUR, 4, 4)));
    Assertions.assertEquals(2, hours.size());
    MetricPoint first = hours.get(0);
    Assertions.assertEquals(hour, first.ts());
    Assertions.assertEquals(HOUR, first.step());
    Assertions.assertEquals(5, first.count());
    Assertions.assertEquals(1, first.errors());
    Assertions.assertEquals(50.0, first.sumMs());
    Assertions.assertEquals(5, java.util.Arrays.stream(first.buckets()).sum());
  }

  @Test
  @DisplayName("After a restart the stored minutes of the open hour are part of its rollup")
  void seedOpenHour() {
    long hour = 10 * HOUR;
    MetricDeriver deriver = new MetricDeriver(100);
    deriver.seed(List.of(minute(hour, 3, 1)));
    deriver.record("api", "/orders", "GET", hour + 20 * MINUTE, 10, false);
    MetricDeriver.Drained drained = deriver.drain(hour + HOUR + 5 * MINUTE);
    Assertions.assertEquals(1, drained.minutes().size());
    Assertions.assertEquals(1, drained.hours().size());
    Assertions.assertEquals(4, drained.hours().get(0).count());
  }

  @Test
  @DisplayName("On shutdown every minute is handed over, the open ones too; the issues count apart")
  void drainAll() {
    long now = System.currentTimeMillis();
    MetricDeriver deriver = new MetricDeriver(1);
    deriver.record("api", "/a", "GET", now, 5, false);
    deriver.recordIssue("api", "fp1", now);
    deriver.recordIssue("api", "fp1", now);
    List<MetricPoint> points = deriver.drainAll();
    Assertions.assertEquals(2, points.size());
    MetricPoint issue = points.stream().filter(p -> MetricDeriver.ISSUE.equals(p.method()))
        .findFirst().orElseThrow();
    Assertions.assertEquals("fp1", issue.route());
    Assertions.assertEquals(2, issue.count());
    Assertions.assertTrue(MetricDeriver.special(MetricDeriver.ISSUE));
    Assertions.assertTrue(deriver.drainAll().isEmpty());
  }
}
